window.LOCAL_FALLBACK_TEMPLATES = FALLBACK_TEMPLATES;

// Initialize Supabase client
let supabaseClient = null;

function initSupabase() {
    if (typeof supabase !== 'undefined') {
        try {
            if (!SUPABASE_URL || SUPABASE_URL.includes('YOUR_PROJECT_ID') || !SUPABASE_ANON_KEY || SUPABASE_ANON_KEY.includes('YOUR_SUPABASE_ANON_KEY')) {
                console.info('ℹ️ Supabase credentials not set — QOVRIX running in standalone offline mode (113 templates ready)');
                return null;
            }
            supabaseClient = supabase.createClient(SUPABASE_URL, SUPABASE_ANON_KEY);
            console.log('✅ Supabase initialized successfully');
            return supabaseClient;
        } catch(e) {
            console.warn('Supabase init notice:', e.message);
            return null;
        }
    } else {
        console.warn('Supabase SDK not loaded - using local storage & embedded templates');
        return null;
    }
}

// Get Supabase client instance
function getSupabase() {
    if (!supabaseClient) {
        return initSupabase();
    }
    return supabaseClient;
}

// Database Operations for Templates
const TemplateDB = {
    // Get all templates (optionally filter by business_type)
    async getAllTemplates(businessType = 'all') {
        const supabase = getSupabase();
        let list = [];
        
        if (supabase) {
            try {
                let query = supabase
                    .from('templates')
                    .select('*')
                    .order('created_at', { ascending: false });
                
                if (businessType && businessType !== 'all') {
                    query = query.eq('business_type', businessType);
                }
                
                const { data, error } = await query;
                if (!error && data && data.length > 0) {
                    list = data;
                }
            } catch (err) {
                console.warn('Supabase fetch error, using local templates:', err.message);
            }
        }
        
        // If Supabase returned nothing or offline, use rich fallback catalog
        if (!list || list.length === 0) {
            list = FALLBACK_TEMPLATES;
            if (businessType && businessType !== 'all') {
                list = list.filter(t => t.business_type === businessType || t.business_type === 'all');
            }
        }
        return list;
    },
    
    // Get templates by category AND business type
    async getTemplatesByCategory(category, businessType = 'all') {
        const all = await this.getAllTemplates(businessType);
        if (!category || category === 'all') return all;
        return all.filter(t => (t.category || '').toLowerCase() === category.toLowerCase());
    },
    
    // Get templates by business type only
    async getTemplatesByBusinessType(businessType) {
        return this.getAllTemplates(businessType);
    },
    
    // Search templates
    async searchTemplates(searchTerm, businessType = 'all') {
        const term = (searchTerm || '').toLowerCase().trim();
        const all = await this.getAllTemplates(businessType);
        if (!term) return all;
        return all.filter(t => 
            (t.name && t.name.toLowerCase().includes(term)) ||
            (t.category && t.category.toLowerCase().includes(term)) ||
            (t.business_type && t.business_type.toLowerCase().includes(term))
        );
    },
    
    // Add new template
    async addTemplate(templateData) {
        const supabase = getSupabase();
        if (supabase) {
            try {
                const { data, error } = await supabase
                    .from('templates')
                    .insert([{
                        name: templateData.name,
                        category: templateData.category,
                        business_type: templateData.businessType || 'all',
                        bg_color: templateData.bgColor || templateData.background,
                        text_color: templateData.textColor,
                        elements: templateData.elements,
                        created_at: new Date().toISOString()
                    }])
                    .select();
                if (!error && data) return data[0];
            } catch(e) {}
        }
        
        // Save to local templates
        templateData.id = templateData.id || 'tpl_' + Date.now();
        FALLBACK_TEMPLATES.unshift(templateData);
        try {
            localStorage.setItem('posterTemplates', JSON.stringify(FALLBACK_TEMPLATES));
        } catch(e) {}
        return templateData;
    }
};

// Database Operations for User Projects (Local + Cloud Sync)
const ProjectDB = {
    // Get user's projects
    async getUserProjects(userId) {
        let localProjects = [];
        try {
            const raw = localStorage.getItem('savedProjects');
            if (raw) localProjects = JSON.parse(raw);
        } catch (e) {
            console.error('Error reading savedProjects:', e);
        }

        const supabase = getSupabase();
        if (supabase && userId) {
            try {
                const { data, error } = await supabase
                    .from('user_projects')
                    .select('*')
                    .eq('user_id', userId)
                    .order('updated_at', { ascending: false });
                    
                if (!error && data && data.length > 0) {
                    // Merge Supabase with local (deduplicate by id)
                    const map = new Map();
                    localProjects.forEach(p => map.set(p.id, p));
                    data.forEach(p => {
                        map.set(p.id, {
                            ...p,
                            backgroundColor: p.background,
                            canvasWidth: p.width,
                            canvasHeight: p.height,
                            date: new Date(p.updated_at || p.created_at).toLocaleDateString()
                        });
                    });
                    return Array.from(map.values());
                }
            } catch (err) {
                console.warn('Supabase projects fetch error:', err.message);
            }
        }
        return localProjects;
    },
    
    // Get single project by ID
    async getProject(projectId) {
        // Check localStorage first
        try {
            const raw = localStorage.getItem('savedProjects');
            if (raw) {
                const list = JSON.parse(raw);
                const found = list.find(p => String(p.id) === String(projectId));
                if (found) return found;
            }
        } catch (e) {}

        const supabase = getSupabase();
        if (supabase) {
            try {
                const { data, error } = await supabase
                    .from('user_projects')
                    .select('*')
                    .eq('id', projectId)
                    .single();
                if (!error && data) return data;
            } catch (e) {}
        }
        return null;
    },
    
    // Save new project with complete state
    async saveProject(projectData) {
        const id = projectData.id || 'proj_' + Date.now();
        const now = new Date();
        const dateStr = now.toLocaleDateString('en-US', { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' });
        
        const projectRecord = {
            id: id,
            name: projectData.name || 'Untitled Poster',
            business_type: projectData.businessType || projectData.business_type || 'all',
            background: projectData.background || projectData.backgroundColor || '#ffffff',
            backgroundColor: projectData.background || projectData.backgroundColor || '#ffffff',
            elements: projectData.elements || [],
            width: projectData.width || projectData.canvasWidth || 800,
            height: projectData.height || projectData.canvasHeight || 1000,
            canvasWidth: projectData.width || projectData.canvasWidth || 800,
            canvasHeight: projectData.height || projectData.canvasHeight || 1000,
            date: dateStr,
            metadata: {
                businessDetails: projectData.businessDetails || null,
                currentTemplate: projectData.currentTemplate || null
            },
            created_at: now.toISOString(),
            updated_at: now.toISOString()
        };

        // Always save to localStorage
        try {
            let projects = [];
            const raw = localStorage.getItem('savedProjects');
            if (raw) projects = JSON.parse(raw);
            
            const existingIndex = projects.findIndex(p => String(p.id) === String(id));
            if (existingIndex >= 0) {
                projects[existingIndex] = { ...projects[existingIndex], ...projectRecord };
            } else {
                projects.unshift(projectRecord);
            }
            localStorage.setItem('savedProjects', JSON.stringify(projects));
            localStorage.setItem('posterProject', JSON.stringify(projectRecord));
        } catch (e) {
            console.error('Error saving project to localStorage:', e);
        }

        // Also attempt cloud save if user logged in
        const supabase = getSupabase();
        if (supabase) {
            try {
                const { data: { user } } = await supabase.auth.getUser();
                if (user) {
                    const { data, error } = await supabase
                        .from('user_projects')
                        .insert([{
                            user_id: user.id,
                            name: projectRecord.name,
                            business_type: projectRecord.business_type,
                            background: projectRecord.background,
                            elements: projectRecord.elements,
                            width: projectRecord.width,
                            height: projectRecord.height,
                            metadata: projectRecord.metadata,
                            created_at: projectRecord.created_at,
                            updated_at: projectRecord.updated_at
                        }])
                        .select();
                    if (!error && data) {
                        projectRecord.cloud_id = data[0].id;
                    }
                }
            } catch (err) {
                console.warn('Cloud sync skipped:', err.message);
            }
        }

        return projectRecord;
    },
    
    // Update existing project
    async updateProject(projectId, projectData) {
        projectData.id = projectId;
        return this.saveProject(projectData);
    },
    
    // Delete project
    async deleteProject(projectId) {
        let deleted = false;
        try {
            const raw = localStorage.getItem('savedProjects');
            if (raw) {
                let projects = JSON.parse(raw);
                projects = projects.filter(p => String(p.id) !== String(projectId));
                localStorage.setItem('savedProjects', JSON.stringify(projects));
                deleted = true;
            }
        } catch (e) {}

        const supabase = getSupabase();
        if (supabase) {
            try {
                await supabase.from('user_projects').delete().eq('id', projectId);
                deleted = true;
            } catch(e) {}
        }
        return deleted;
    }
};

// Authentication Operations
const AuthDB = {
    async getCurrentUser() {
        return getCurrentUser();
    },
    async signIn(email, password) {
        const user = {
            id: 'user_' + Date.now(),
            email: email,
            displayName: email.split('@')[0],
            role: email.includes('admin') ? 'admin' : 'user'
        };
        localStorage.setItem('ai_poster_user', JSON.stringify(user));
        return user;
    },
    async signUp(email, password, name) {
        const user = {
            id: 'user_' + Date.now(),
            email: email,
            displayName: name || email.split('@')[0],
            role: 'user'
        };
        localStorage.setItem('ai_poster_user', JSON.stringify(user));
        return user;
    },
    async signOut() {
        localStorage.removeItem('ai_poster_user');
        return true;
    }
};

// Business Details Database Operations
const BusinessDetailsDB = {
    async getBusinessDetails() {
        const raw = localStorage.getItem('businessDetails');
        if (raw) {
            try { return JSON.parse(raw); } catch (e) {}
        }
        return {
            name: 'Your Brand',
            tagline: 'Creativity that Inspires',
            color: '#6366f1',
            phone: '+91 98765 43210',
            website: 'www.yourbrand.com',
            email: 'hello@yourbrand.com',
            address: 'City Center, Main Street'
        };
    },
    async saveBusinessDetails(details) {
        localStorage.setItem('businessDetails', JSON.stringify(details));
        return details;
    }
};

// Helper function to get current user from localStorage
function getCurrentUser() {
    const savedUser = localStorage.getItem('ai_poster_user');
    if (savedUser) {
        try {
            const u = JSON.parse(savedUser);
            if (!u.id) u.id = 'usr_guest';
            return u;
        } catch(e) {}
    }
    return {
        id: 'usr_guest',
        displayName: 'Guest Designer',
        email: 'designer@example.com',
        role: 'user'
    };
}

// Initialize Supabase when script loads
document.addEventListener('DOMContentLoaded', () => {
    initSupabase();
});

// Export for use in other scripts
window.SupabaseConfig = {
    initSupabase,
    getSupabase,
    TemplateDB,
    ProjectDB,
    AuthDB,
    BusinessDetailsDB,
    getCurrentUser,
    FALLBACK_TEMPLATES
};
